import koffi from "koffi";
import { promisify } from "node:util";

//#region src/index.ts
const os = process.platform;
const arch = process.arch;
const prefixForOs = os === "win32" ? "" : "lib";
const extForOs = os === "win32" ? ".dll" : os === "darwin" ? ".dylib" : ".so";
const importUriToPath = (importUri) => {
	if (os === "win32") return importUri.substring(8);
	else return importUri.substring(7);
};
const lib = koffi.load(importUriToPath(import.meta.resolve(`../lib/${os}-${arch}/${prefixForOs}LagrangeCodec${extForOs}`)));
const CbCodec = koffi.proto("cb_codec", "void", [
	"void *",
	"uint8_t *",
	"int"
]);
const VideoInfo = koffi.struct("VideoInfo", {
	width: "int32_t",
	height: "int32_t",
	duration: "int64_t"
});
const audioToPcmNative = lib.func("audio_to_pcm", "int", [
	"uint8_t *",
	"int",
	koffi.pointer(CbCodec),
	"void *"
]);
const silkDecodeNative = lib.func("silk_decode", "int", [
	"uint8_t *",
	"int",
	koffi.pointer(CbCodec),
	"void *"
]);
const silkEncodeNative = lib.func("silk_encode", "int", [
	"uint8_t *",
	"int",
	koffi.pointer(CbCodec),
	"void *"
]);
const videoFirstFrameNative = lib.func("video_first_frame", "int", [
	"uint8_t *",
	"int",
	koffi.out(koffi.pointer("uint8_t", 2)),
	koffi.out(koffi.pointer("int32_t"))
]);
const videoGetSizeNative = lib.func("video_get_size", "int", [
	"uint8_t *",
	"int",
	koffi.out(koffi.pointer(VideoInfo))
]);
async function collectByCallback(invoke, apiName) {
	const chunks = [];
	const ret = await invoke((_userdata, p, len) => {
		if (!p || len <= 0) return;
		const chunk = koffi.decode(p, "uint8_t", len);
		chunks.push(Buffer.from(chunk));
	});
	if (ret !== 0) throw new Error(`${apiName} failed with code ${ret}`);
	return chunks.length === 0 ? Buffer.alloc(0) : Buffer.concat(chunks);
}
async function audioToPcm(audio) {
	return collectByCallback((cb) => promisify(audioToPcmNative.async)(audio, audio.length, cb, null), "audio_to_pcm");
}
async function silkDecode(silk) {
	return collectByCallback((cb) => promisify(silkDecodeNative.async)(silk, silk.length, cb, null), "silk_decode");
}
async function silkEncode(pcm) {
	return collectByCallback((cb) => promisify(silkEncodeNative.async)(pcm, pcm.length, cb, null), "silk_encode");
}
async function videoFirstFrame(video) {
	const out = [null];
	const outLen = [0];
	const ret = await promisify(videoFirstFrameNative.async)(video, video.length, out, outLen);
	if (ret !== 0) throw new Error(`video_first_frame failed with code ${ret}`);
	if (!out[0] || outLen[0] <= 0) return Buffer.alloc(0);
	const data = koffi.decode(out[0], "uint8_t", outLen[0]);
	return Buffer.from(data);
}
async function videoGetSize(video) {
	const info = {};
	const ret = await promisify(videoGetSizeNative.async)(video, video.length, info);
	if (ret !== 0) throw new Error(`video_get_size failed with code ${ret}`);
	return {
		width: info.width ?? 0,
		height: info.height ?? 0,
		duration: Number(info.duration ?? 0)
	};
}

//#endregion
export { audioToPcm, silkDecode, silkEncode, videoFirstFrame, videoGetSize };